func entityHasDerivedAttr(stepName, attrName string) bool {
	if attrs, ok := entityDerivedEvaluators[strings.ToUpper(strings.TrimSpace(stepName))]; ok {
		for name := range attrs {
			if strings.EqualFold(name, attrName) {
				return true
			}
		}
	}
	return false
}
